--sk-folder-fill-active.default:
light-dark(
      color-mix(in oklab, var(--color-text-primary) 10%, var(--color-bg-surface-raised)),
      var(--color-bg-surface-raised)
    )

--sk-media-gradient-ink.default:
color-mix(
      in oklch,
      var(--sk-media-gradient-base) var(--sk-media-gradient-opacity),
      transparent
    )

--sk-media-gradient-ink-mid.default:
color-mix(
      in oklch,
      var(--sk-media-gradient-base) calc(var(--sk-media-gradient-opacity) * 0.35),
      transparent
    )

--sk-media-gradient-tint-edge.default:
color-mix(
      in oklch,
      var(--sk-media-gradient-tint) calc(var(--sk-media-gradient-mix) * 1.1),
      transparent
    )

--sk-media-gradient-tint-mid.default:
color-mix(
      in oklch,
      var(--sk-media-gradient-tint) calc(var(--sk-media-gradient-mix) * 0.4),
      transparent
    )

--sk-slider-track.default:
light-dark(
      var(--color-bg-surface-sunken),
      color-mix(in oklab, var(--color-text-primary) 24%, var(--color-bg-surface))
    )
